const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const root = process.cwd();
const banned = fs.existsSync('11_Config/banned_topics.txt') ? fs.readFileSync('11_Config/banned_topics.txt','utf8').toLowerCase().split(/\r?\n/).filter(Boolean) : [];
const usedPath = path.join('state','used_topics.json');
const used = fs.existsSync(usedPath) ? JSON.parse(fs.readFileSync(usedPath,'utf8')) : [];
const seen = new Set(used.map(x => String(x.topic || '').toLowerCase()));
function norm(t){return String(t||'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();}
let candidates=[];
for (const item of items) {
  const body = item.json.body || item.json.data || item.json;
  const text = typeof body === 'string' ? body : JSON.stringify(body);
  const titles = [...text.matchAll(/<title><!\[CDATA\[(.*?)\]\]><\/title>|<title>(.*?)<\/title>|"title"\s*:\s*"([^"]+)"/g)].map(m => norm(m[1]||m[2]||m[3]));
  candidates.push(...titles);
}
const fallback = fs.existsSync('11_Config/topics.txt') ? fs.readFileSync('11_Config/topics.txt','utf8').split(/\r?\n/).filter(Boolean).map(s => `${s} breakthrough creators should understand today`) : [];
candidates = candidates.length ? candidates : fallback;
const out=[];
for (const title of candidates) {
  const lower=title.toLowerCase();
  if (title.length < 12 || seen.has(lower) || banned.some(b => lower.includes(b))) continue;
  if (out.some(x => x.title.toLowerCase() === lower)) continue;
  out.push({id: crypto.createHash('sha256').update(lower).digest('hex').slice(0,16), title, angle:'Explain why this matters in under 40 seconds', keywords:title, source:'research-workflow'});
  if (out.length === 10) break;
}
fs.mkdirSync('output',{recursive:true}); fs.writeFileSync('output/topics.json', JSON.stringify(out,null,2));
return out.map(json => ({json}));

